//
// FrostEngine's Lua host provider for LuaLS (FEC-10a, PLAN.md Appendix C R1; on the host API of
// LUA-13, lua_host.hpp, so the Lua module itself holds no FrostEngine code): what a FrostEngine
// workspace's LuaLS learns from the engine's own files instead of a list kept in FrostIDE. The
// globals and the Lua version come from the engine's generated scripting reference,
// Docs/ScriptingAPI.md ("Generated by ScriptApiDocs::GenerateMarkdown() from the binding
// registrations"), which the engine writes from the same registrations its script sandbox installs
// (ScriptEngine::InstallSandbox, ScriptApiRegistry::InstallModules). The library is the engine's
// generated definitions folder (.frost/lua-api) of every FrostEngine project the workspace holds,
// when the engine has written it.
/*
 * Which names are globals follows the reference's own section introductions: the Globals table
 * (global functions and values), Namespaces ("global tables"), Types ("calling the type's global
 * table constructs a value"), Enums (read-only global tables) and the Lua standard library subset.
 * The Script class section ("these are not Lua globals") and Components (proxies returned by
 * Entity:GetComponent, named by strings) are not globals. A heading or table entry contributes
 * the identifier it starts with ("Vec3", "Wait" from "Wait(seconds: number)"); dotted headings
 * contribute their first part.
 *
 * Workspaces. A FrostEngine project root holds a <stem>.frostproj or <stem>.feproject
 * (isFrostEngineProjectRoot); an engine checkout holds the generated reference itself. The
 * reference is looked up in the root and then in its ancestors (a sample project inside the
 * engine's repository finds the engine's reference), at most kMaxReferenceDepth levels up.
 * Without a reference no globals are claimed: LuaLS reports what it reports, and `problem` says
 * why (the truth rule, ADR 0078).
 *
 * Thread safety: pure functions over `fs`; thread-safe as the file system is.
 */
#pragma once

#include "frost/core/error.hpp"
#include "frost/io/file_system.hpp"
#include "frost/lang/json.hpp"
#include "frost/lang/lua_host.hpp"

#include <cstddef>
#include <memory>
#include <string>
#include <string_view>
#include <vector>

namespace frost::lang {

/*
 * FrostEngine project detection, the one rule every feature uses (the FrostEngine tool window and
 * the LuaLS provider): a project file is named <stem>.frostproj or <stem>.feproject with a
 * non-empty stem, ASCII case ignored on every platform. isFrostEngineProjectRoot is true when
 * `root` directly holds such a regular file (symlinks and directories do not count); one directory
 * listing, false when `root` is empty or cannot be read. Thread-safe as `fs` is.
 */
[[nodiscard]] bool isFrostEngineProjectFileName(std::string_view name) noexcept;
[[nodiscard]] bool isFrostEngineProjectRoot(io::IFileSystem& fs, std::string_view root);
// A FrostEngine project root (isFrostEngineProjectRoot), whose Lua gets the provider's contribution.
[[nodiscard]] bool isFrostEngineLuaWorkspace(io::IFileSystem& fs, std::string_view root);

// The script path and the builtins a FrostEngine project's sandbox removes (ScriptEngine::InstallSandbox).
inline constexpr std::string_view kFrostEngineScriptPath = "Assets/Scripts/?.lua";

// The engine's generated reference, relative to the engine checkout.
inline constexpr std::string_view kFrostEngineScriptApiReference = "Docs/ScriptingAPI.md";
// The line the engine's generator writes at the top of the reference (ScriptApiDocs::GenerateMarkdown).
inline constexpr std::string_view kFrostEngineScriptApiMarker = "Generated by ScriptApiDocs::GenerateMarkdown()";
// The engine's generated LuaLS definitions folder, relative to a FrostEngine project
// (Frost::ScriptLuaDefinitions::DirectoryName).
inline constexpr std::string_view kFrostEngineLuaApiDirectory = ".frost/lua-api";
// How many ancestors of a workspace root are searched for the reference.
inline constexpr std::size_t kMaxReferenceDepth = 4;

// What the generated reference declares.
struct FrostEngineScriptApi {
    std::vector<std::string> globals; // Sorted, unique identifiers.
    std::string runtimeVersion;       // From the _VERSION entry, e.g. "Lua 5.4"; "" when it names none.
};

/*
 * Parses the generated reference `markdown` (header comment). Errors: InvalidArgument when the
 * text lacks kFrostEngineScriptApiMarker (not the engine's generated file) or declares no global.
 * O(size).
 */
[[nodiscard]] Result<FrostEngineScriptApi> parseFrostEngineScriptApi(std::string_view markdown);

// What one workspace root gets (discoverFrostEngineLua).
struct FrostEngineLuaProfile {
    bool frostEngine = false; // A FrostEngine project root or an engine checkout.
    bool projectRoot = false; // The root holds a FrostEngine project file.
    std::string reference;    // The reference read, absolute; "" when none was found or it did not parse.
    FrostEngineScriptApi api; // From `reference`; empty without one.
    // The generated definition folders that exist, relative to the root ('/'-separated):
    // .frost/lua-api of the root project, or of the projects up to two levels below an engine checkout.
    std::vector<std::string> library;
    // An engine checkout's FrostEngine projects up to two levels below it, relative ('/'-separated),
    // sorted; empty for a project root.
    std::vector<std::string> projects;
    std::string problem; // English, for the log: why no globals came from the engine ("" when they did).
};

/*
 * The FrostEngine profile of the workspace `root` (absolute): project detection, the reference
 * lookup and its parse, and the existing generated definition folders. Not a FrostEngine workspace
 * (frostEngine false) when the root is neither a project root nor an engine checkout. Reads at most
 * kMaxReferenceDepth + 1 small directories' entries, the reference (about 1 MB) and up to two
 * directory levels of listings below an engine checkout.
 */
[[nodiscard]] FrostEngineLuaProfile discoverFrostEngineLua(io::IFileSystem& fs, std::string_view root);

/*
 * The LuaLS contribution for a workspace with `profile` (nullopt when it is no FrostEngine
 * workspace): runtime.path kFrostEngineScriptPath, the io, package, os and debug builtins disabled,
 * the reference's runtimeVersion when it names one (else the user's setting stays), the reference's
 * globals (diagnostics.globals) and workspace.library (profile.library when it found any, else the
 * project convention .frost/lua-api). `note` carries profile.problem or what was read.
 */
[[nodiscard]] std::optional<LuaHostContribution> frostEngineLuaContribution(const FrostEngineLuaProfile& profile);
// The client configuration of one FrostEngine folder alone: composeLuaConfiguration over its
// contribution (luaDefaults(runtimeVersion) when `profile` is no FrostEngine workspace).
[[nodiscard]] Json frostEngineLuaDefaults(std::string runtimeVersion, const FrostEngineLuaProfile& profile);

// The FrostEngine Lua host (lua_host.hpp): discoverFrostEngineLua, then frostEngineLuaContribution.
class FrostEngineLuaProvider final : public ILuaHostProvider {
public:
    static constexpr std::string_view kName = "FrostEngine";
    [[nodiscard]] std::string_view name() const noexcept override { return kName; }
    [[nodiscard]] std::optional<LuaHostContribution> contribute(io::IFileSystem& fs, std::string_view folder) override;
};

} // namespace frost::lang
